import { Dispatch, SetStateAction, useEffect, useState } from "react";
import { socket } from "../socket";
import { BoardState } from "../types";

export function useBoard() {
  const [board, setBoard] = useState<BoardState | null>(null);

  useEffect(() => {
    // initial load
    socket.on("board:init", (data: BoardState) => {
      setBoard(data);
    });
    socket.on("connect", () => {
  console.log("✅ connected to server");
});

    // updates from other users
    socket.on("board:update", (data: BoardState) => {
      setBoard(data);
    });

    socket.on("card:create", (payload) => {
      setBoard((prev) => {
        if (!prev) return prev;

        const { card, columnId } = payload;

        return {
          ...prev,
          cards: {
            ...prev.cards,
            [card.id]: card,
          },
          columns: {
            ...prev.columns,
            [columnId]: {
              ...prev.columns[columnId],
              cardIds: [...prev.columns[columnId].cardIds, card.id],
            },
          },
        };
      });
    });

    socket.on("card:update", (payload) => {
      setBoard((prev) => {
        if (!prev) return prev;

        const { cardId, updates } = payload;

        return {
          ...prev,
          cards: {
            ...prev.cards,
            [cardId]: {
              ...prev.cards[cardId],
              ...updates,
            },
          },
        };
      });
    });

    socket.on("card:delete", (payload) => {
      setBoard((prev) => {
        if (!prev) return prev;

        const { cardId, columnId } = payload;

        const newCards = { ...prev.cards };
        delete newCards[cardId];

        return {
          ...prev,
          cards: newCards,
          columns: {
            ...prev.columns,
            [columnId]: {
              ...prev.columns[columnId],
              cardIds: prev.columns[columnId].cardIds.filter(
                (id) => id !== cardId,
              ),
            },
          },
        };
      });
    });

    return () => {
      socket.off("board:init");
      socket.off("board:update");

      socket.off("card:create");
      socket.off("card:update");
      socket.off("card:delete");
    };
  }, []);

  const updateBoard: Dispatch<SetStateAction<BoardState>> = (value) => {
    setBoard((prev) => {
      if (!prev) return prev;

      const newBoard = typeof value === "function" ? value(prev) : value;

      socket.emit("board:update", newBoard);

      return newBoard;
    });
  };
  return {
    board,
    setBoard: updateBoard,
  };
}
